ARTICLES = [
 {'_id':'profile-article-01','title':'الألياف الضوئية: أساس الاتصال عالي السعة','slug':'fiber-optics-high-capacity-connectivity','summary':'نظرة مبسطة على دور الألياف الضوئية في ربط المواقع ونقل البيانات.','content':'ما المقصود بالألياف الضوئية؟\nتستخدم الألياف الضوئية نبضات الضوء لنقل البيانات عبر ألياف دقيقة، وتُستخدم في شبكات الوصول والعمود الفقري والربط بين المواقع.\n\nأين تُستخدم؟\nيمكن أن تدخل في شبكات الاتصالات، وربط المباني ومراكز البيانات، وشبكات المؤسسات. ويعتمد اختيار نوع الألياف والتصميم على المسافة والسعة والبيئة ومتطلبات المشروع.\n\nما الذي يتطلبه التنفيذ؟\nيشمل العمل عادةً تخطيط المسارات، واختيار الكابلات والمكونات، واللحام والإنهاء، ثم الفحص والتوثيق.\n\nتنويه: مادة تعريفية تجريبية لأغراض اختبار مركز المعرفة، وليست استشارة تصميم لمشروع محدد.','type':'article','category_id':'profile-article-category-01','cover_image_url':IMG_FIBER,'author':'فريق المحتوى – مادة تجريبية','published_at':'2026-11-10','order':1,'published':True,'is_demo':True,'en':{'title':'Fiber Optics: A Foundation for High-Capacity Connectivity','summary':'An introduction to the role of fiber optics in connecting sites and carrying data.','content':'What is fiber optics?\nFiber optics use pulses of light to carry data through thin fibers. They are used in access networks, backbones and links between sites.\n\nWhere is it used?\nFiber can be used in telecommunications, building and data center connectivity, and enterprise networks. Selection depends on distance, capacity, environment and project requirements.\n\nWhat does deployment involve?\nWork commonly includes route planning, cable and component selection, splicing and termination, followed by testing and documentation.\n\nNote: Demo educational content for testing the knowledge center, not a design recommendation for a specific project.'}},
 {'_id':'profile-article-02','title':'مراكز البيانات: عناصر البنية الأساسية','slug':'data-centers-infrastructure-elements','summary':'تعرف على الرفوف والطاقة والتبريد والكابلات والاتصال داخل مراكز البيانات.','content':'ما الذي يتكون منه مركز البيانات؟\nتضم بيئة مركز البيانات الخوادم وأنظمة التخزين والشبكات والرفوف والكابلات المنظمة، إضافة إلى الطاقة الاحتياطية والتبريد ومراقبة البيئة.\n\nلماذا يعد التخطيط مهمًا؟\nيساعد التخطيط على تنظيم المسارات، وإتاحة الصيانة، وإدارة الطاقة والتبريد، ودعم التوسع المستقبلي.\n\nمراحل العمل\nقد تشمل دراسة الموقع، والتصميم، وتجهيز البنية، والاختبارات، والتوثيق والتسليم وفق نطاق المشروع.\n\n> مقال توضيحي تجريبي لا يصف مركز بيانات نفذته الشركة.','type':'article','category_id':'profile-article-category-02','cover_image_url':IMG_DATACENTER,'author':'فريق المحتوى – مادة تجريبية','published_at':'2026-11-10','order':2,'published':True,'is_demo':True,'en':{'title':'Data Centers: Core Infrastructure Elements','summary':'An overview of racks, power, cooling, cabling and connectivity in data centers.','content':'What makes up a data center?\nA data center environment includes servers, storage, networks, racks and structured cabling, alongside backup power, cooling and environmental monitoring.\n\nWhy does planning matter?\nPlanning helps organize pathways, improve serviceability, manage power and cooling, and support future expansion.\n\nWork phases\nDepending on scope, work may include site assessment, design, infrastructure preparation, testing, documentation and handover.\n\n> Illustrative demo article; it does not describe a data center delivered by the company.'}},
 {'_id':'profile-article-03','title':'مبادئ أساسية في الأمن السيبراني للمؤسسات','slug':'cybersecurity-basics-for-organizations','summary':'مفاهيم عامة حول إدارة الوصول والتحديثات والنسخ الاحتياطي والوعي الأمني.','content':'الأمن مسؤولية مستمرة\nتحتاج المؤسسات إلى سياسات واضحة لإدارة الحسابات والصلاحيات، وتحديث الأنظمة، وحماية الأجهزة والبيانات، ومراجعة النسخ الاحتياطية.\n\nعناصر أساسية\n• منح الصلاحيات وفق الحاجة الوظيفية.\n• تحديث الأنظمة والبرامج بصورة منتظمة.\n• توعية المستخدمين بمخاطر الرسائل والروابط غير الموثوقة.\n• اختبار إجراءات النسخ الاحتياطي والاستعادة.\n• توثيق الحوادث ومراجعة الإجراءات.\n\nتنويه: مادة توعوية عامة لأغراض العرض والاختبار، ولا تمثل تدقيقًا أمنيًا أو تقييمًا لشركة بعينها.','type':'article','category_id':'profile-article-category-03','cover_image_url':IMG_CYBER,'author':'فريق المحتوى – مادة تجريبية','published_at':'2026-11-10','order':3,'published':True,'is_demo':True,'en':{'title':'Cybersecurity Basics for Organizations','summary':'General concepts around access management, updates, backups and security awareness.','content':'Security is an ongoing responsibility\nOrganizations need clear policies for account and permission management, system updates, endpoint and data protection, and backup reviews.\n\nEssential practices\n• Grant permissions according to job needs.\n• Keep systems and software updated.\n• Help users recognize suspicious messages and untrusted links.\n• Test backup and recovery procedures.\n• Document incidents and review procedures.\n\nNote: General awareness demo content, not a security audit or assessment of any organization.'}},
 {'_id':'profile-article-04','title':'إنترنت الأشياء ومراقبة الأصول والمرافق','slug':'iot-asset-facility-monitoring','summary':'كيف تساعد المستشعرات والبوابات ولوحات المتابعة في تكوين صورة تشغيلية عن الأصول.','content':'ما هو إنترنت الأشياء؟\nيربط إنترنت الأشياء أجهزة ومستشعرات وبوابات اتصال لجمع البيانات من الأصول والمرافق وإرسالها إلى أنظمة المتابعة.\n\nأمثلة استخدام توضيحية\nيمكن استخدام هذا النموذج لمراقبة مؤشرات بيئية أو استهلاك الطاقة أو حالة معدات، بحسب المستشعرات والاتصال ومتطلبات الخصوصية.\n\nمكونات الحل\nقد يتضمن الحل مستشعرات، وبوابات اتصال، وتخزين بيانات، ولوحات متابعة، وتنبيهات وتحليلات.\n\nتنويه: سيناريو توضيحي تجريبي وليس نظامًا منشورًا لدى عميل حقيقي.','type':'article','category_id':'profile-article-category-04','cover_image_url':IMG_IOT,'author':'فريق المحتوى – مادة تجريبية','published_at':'2026-11-10','order':4,'published':True,'is_demo':True,'en':{'title':'IoT for Asset and Facility Monitoring','summary':'How sensors, gateways and dashboards can provide operational visibility into assets.','content':'What is the Internet of Things?\nIoT connects devices, sensors and gateways to collect data from assets and facilities and send it to monitoring systems.\n\nIllustrative use cases\nThis model may monitor environmental indicators, energy consumption or equipment status, depending on sensors, connectivity and privacy requirements.\n\nSolution components\nA solution may include sensors, gateways, data storage, dashboards, alerts and analytics.\n\nNote: Illustrative demo scenario, not a system deployed for a real client.'}},
]



